const ageDays=(birth,when)=>Math.floor((Date.parse(when+"T00:00:00Z")-Date.parse(birth+"T00:00:00Z"))/86400000);
const ageText=(birth,when)=>{const n=ageDays(birth,when);return n<0?"Ngày không hợp lệ":Math.floor(n/7)+" tuần "+n%7+" ngày"};
