async function start(){const status=$("sessionStatus");if(status){status.hidden=false;status.textContent="Đang kiểm tra đăng nhập…";}const sessionResult=await Promise.race([db.auth.getSession(),new Promise((_,reject)=>setTimeout(()=>reject(new Error("Kiểm tra phiên đăng nhập quá thời gian chờ.")),10000))]);const {data,error}=sessionResult;user=data?.session?.user;if(error||!user){$("loginNotice").hidden=false;if(status){status.hidden=false;status.textContent=error?.message||"Chưa đăng nhập. Vui lòng đăng nhập lại rồi tải trang.";}return;}
const {data:p,error:pe}=await db.from("profiles").select("user_id,username,display_name,due_date").eq("user_id",user.id).single();if(pe||!p){$("loginNotice").hidden=false;$("sessionStatus").textContent="Không đọc được hồ sơ.";return;}profile=p;
if(user.app_metadata?.role==="admin"){$("adminArea").hidden=false;$("sessionStatus").textContent="Đăng nhập quản trị.";await loadDirectory();}else{$("patientArea").hidden=false;$("sessionStatus").textContent="Xin chào "+(p.display_name||p.username);$("measureDate").value=dateToDMY(today());await Promise.all([loadPatientData(),loadVaccineRecords()]);syncVaccineStatusFields();}
}
