function vaccineScheduleDate(birth,months,days=0){if(!birth)return "";const [y,m,d]=birth.split("-").map(Number);const targetMonth=m-1+months;const year=y+Math.floor(targetMonth/12),month=((targetMonth%12)+12)%12;const lastDay=new Date(Date.UTC(year,month+1,0)).getUTCDate();const base=new Date(Date.UTC(year,month,Math.min(d,lastDay)));base.setUTCDate(base.getUTCDate()+days);return base.toISOString().slice(0,10);}
