function renderSymptoms(box,rows,admin){
 box.replaceChildren();
 if(!rows.length){const p=document.createElement("p");p.className="muted";p.textContent=admin?"Chưa có triệu chứng nào được gửi.":"Bạn chưa gửi triệu chứng nào.";box.append(p);return;}
 rows.forEach(row=>{
  const card=document.createElement("article");card.className="person";
  if(admin){const title=document.createElement("strong");title.textContent=row.patient_name+" · "+row.username;card.append(title);}
  const date=document.createElement("small");date.textContent=new Date(row.created_at).toLocaleString("vi-VN");
  const text=document.createElement("p");text.style.whiteSpace="pre-wrap";text.textContent=row.symptoms;
  card.append(date,text);
  if(admin){const del=document.createElement("button");del.className="danger";del.type="button";del.textContent="Xóa";del.addEventListener("click",async()=>{if(!confirm("Xóa ghi nhận triệu chứng này?"))return;const {error}=await db.from("patient_postpartum_maternal_symptoms").delete().eq("id",row.id);if(error){msg("adminMaternalSymptomsStatus","Không xóa được ghi nhận.");return;}await loadAdminMotherSymptoms();});card.append(del);}
  box.append(card);
 });
}
